def min_insertions_to_avoid_zero_sum_subarray(n, array):
    prefix_sum = 0
    prefix_sums_set = {0}
    insertions = 0

    for num in array:
        prefix_sum += num
        if prefix_sum in prefix_sums_set:
            insertions += 1
            prefix_sum = 0
            prefix_sums_set = {0}
        else:
            prefix_sums_set.add(prefix_sum)

    return insertions

