def min_insertions_to_avoid_zero_sum_subarray(n, array):
    prefix_sum = 0
    seen_prefix_sums = {0: -1}
    max_length = 0
    last_seen = {}

    for i in range(n):
        prefix_sum += array[i]

        if prefix_sum in seen_prefix_sums:
            max_length = max(max_length, i - seen_prefix_sums[prefix_sum])
        else:
            seen_prefix_sums[prefix_sum] = i

        last_seen[prefix_sum] = i

    return max(0, n - max_length)

